import React, { useEffect, useMemo, useState } from "react";
import { motion } from "framer-motion";
import { useNavigate } from "react-router-dom";

import InchargeModal from "../components/InchargeModal";
import Navbar from "../components/Navbar";
import RejectBookingModal from "../components/RejectBookingModal";
import Sidebar from "../components/Sidebar";
import { useAppContext } from "../context/AppContext";
import api from "../services/api";
import { formatErrorMessage } from "../utils/errorMessages";

const adminNavItems = [
  { key: "dashboard", label: "Dashboard", icon: "D" },
  { key: "bookings", label: "Bookings", icon: "B" },
  { key: "schedule", label: "Schedule", icon: "S" },
  { key: "incharges", label: "Incharges", icon: "I" }
];

const tabs = ["pending", "approved", "rejected"];

const formatResourceLabel = (resource, fallbackId) => {
  if (!resource) {
    return `Resource #${fallbackId}`;
  }
  return resource.floor ? `${resource.name} - ${resource.floor}` : resource.name;
};

const AnimatedCounter = ({ value }) => {
  const [displayValue, setDisplayValue] = useState(0);

  useEffect(() => {
    let frameId;
    const start = performance.now();
    const duration = 650;

    const tick = (time) => {
      const progress = Math.min((time - start) / duration, 1);
      setDisplayValue(Math.round(value * progress));
      if (progress < 1) {
        frameId = requestAnimationFrame(tick);
      }
    };

    frameId = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frameId);
  }, [value]);

  return displayValue;
};

const StatCard = ({ tone, icon, label, value, delay }) => (
  <motion.div
    className={`stat-card ${tone}`}
    initial={{ opacity: 0, y: 18 }}
    animate={{ opacity: 1, y: 0 }}
    transition={{ duration: 0.35, delay }}
    whileHover={{ y: -5, scale: 1.01 }}
  >
    <div className="stat-icon">{icon}</div>
    <div>
      <h4>{label}</h4>
      <h2><AnimatedCounter value={value} /></h2>
    </div>
  </motion.div>
);

const StatusBadge = ({ status }) => (
  <span className={`admin-status-badge ${status}`}>{status}</span>
);

const AdminBookingTable = ({ bookings, activeTab, onApprove, onReject }) => (
  <motion.div
    className="admin-pro-table-card card"
    initial={{ opacity: 0, y: 20 }}
    animate={{ opacity: 1, y: 0 }}
    transition={{ duration: 0.3 }}
  >
    <div className="table-wrap">
      <table className="admin-table">
        <thead>
          <tr>
            <th>User</th>
            <th>Resource</th>
            <th>Date</th>
            <th>Time</th>
            <th>Status</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {bookings.length === 0 ? (
            <tr>
              <td colSpan="6" className="empty-table-cell">
                <div className="empty-saas-state">
                  <strong>No bookings yet</strong>
                  <span>New requests will appear here automatically.</span>
                </div>
              </td>
            </tr>
          ) : (
            bookings.map((booking, index) => (
              <motion.tr
                key={booking.id}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.22, delay: index * 0.03 }}
              >
                <td>
                  <strong>{booking.user?.username || "User"}</strong>
                  <span className="table-subtext">{booking.purpose || "No purpose provided"}</span>
                </td>
                <td>{formatResourceLabel(booking.resource, booking.resource_id)}</td>
                <td>{booking.booking_date}</td>
                <td>{booking.start_time?.slice(0, 5)} - {booking.end_time?.slice(0, 5)}</td>
                <td><StatusBadge status={booking.status} /></td>
                <td>
                  {activeTab === "pending" ? (
                    <div className="table-actions">
                      <motion.button
                        type="button"
                        className="action-btn approve"
                        onClick={() => onApprove(booking.id)}
                        whileHover={{ scale: 1.04 }}
                        whileTap={{ scale: 0.97 }}
                      >
                        Approve
                      </motion.button>
                      <motion.button
                        type="button"
                        className="action-btn reject"
                        onClick={() => onReject(booking)}
                        whileHover={{ scale: 1.04 }}
                        whileTap={{ scale: 0.97 }}
                      >
                        Reject
                      </motion.button>
                    </div>
                  ) : (
                    <span className="table-subtext">Processed</span>
                  )}
                </td>
              </motion.tr>
            ))
          )}
        </tbody>
      </table>
    </div>
  </motion.div>
);

const AdminSkeleton = () => (
  <div className="admin-skeleton-grid">
    <div className="skeleton-line" />
    <div className="skeleton-line" />
    <div className="skeleton-line" />
    <div className="skeleton-line" />
  </div>
);

const AdminDashboard = () => {
  const navigate = useNavigate();
  const { incharges, fetchInitialData } = useAppContext();
  const [activeSection, setActiveSection] = useState("dashboard");
  const [activeTab, setActiveTab] = useState("pending");
  const [pendingBookings, setPendingBookings] = useState([]);
  const [schedule, setSchedule] = useState([]);
  const [history, setHistory] = useState([]);
  const [showIncharges, setShowIncharges] = useState(false);
  const [rejectBooking, setRejectBooking] = useState(null);
  const [rejectReason, setRejectReason] = useState("");
  const [rejectLoading, setRejectLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [loading, setLoading] = useState(true);

  const loadData = async () => {
    setLoading(true);
    try {
      const [pendingResponse, scheduleResponse, historyResponse] = await Promise.all([
        api.get("/admin/bookings/pending"),
        api.get("/admin/schedule"),
        api.get("/admin/history"),
        fetchInitialData()
      ]);

      setPendingBookings(pendingResponse.data || []);
      setSchedule(scheduleResponse.data || []);
      setHistory(historyResponse.data || []);
    } catch (error) {
      setMessage(formatErrorMessage(error.response?.data?.detail, "Could not load dashboard data."));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  const handleLogout = () => {
    localStorage.removeItem("token");
    navigate("/login");
  };

  const handleApprove = async (bookingId) => {
    try {
      await api.post(`/admin/bookings/${bookingId}/approve`);
      setMessage("Booking approved.");
      await loadData();
    } catch (error) {
      setMessage(formatErrorMessage(error.response?.data?.detail, "Approval failed."));
    }
  };

  const openRejectModal = (booking) => {
    setRejectBooking(booking);
    setRejectReason("");
  };

  const closeRejectModal = () => {
    setRejectBooking(null);
    setRejectReason("");
    setRejectLoading(false);
  };

  const handleRejectSubmit = async () => {
    if (!rejectBooking || !rejectReason.trim()) {
      return;
    }

    setRejectLoading(true);
    try {
      await api.post(`/admin/bookings/${rejectBooking.id}/reject`, {
        reason: rejectReason.trim()
      });
      setMessage("Booking rejected.");
      closeRejectModal();
      await loadData();
    } catch (error) {
      setMessage(formatErrorMessage(error.response?.data?.detail, "Rejection failed."));
      setRejectLoading(false);
    }
  };

  const handleSidebarSelect = (itemKey) => {
    if (itemKey === "incharges") {
      setShowIncharges(true);
      return;
    }

    setShowIncharges(false);
    setActiveSection(itemKey);
    if (itemKey === "schedule") {
      setActiveTab("approved");
    }
  };

  const approvedBookings = useMemo(
    () => history.filter((booking) => booking.status === "approved"),
    [history]
  );
  const rejectedBookings = useMemo(
    () => history.filter((booking) => booking.status === "rejected"),
    [history]
  );
  const activeBookings = useMemo(() => {
    if (activeTab === "approved") {
      return approvedBookings.length ? approvedBookings : schedule.filter((booking) => booking.status === "approved");
    }
    if (activeTab === "rejected") {
      return rejectedBookings;
    }
    return pendingBookings;
  }, [activeTab, approvedBookings, pendingBookings, rejectedBookings, schedule]);
  const stats = useMemo(() => ({
    total: Math.max(schedule.length, pendingBookings.length + history.length),
    pending: pendingBookings.length,
    approved: approvedBookings.length,
    rejected: rejectedBookings.length
  }), [approvedBookings.length, history.length, pendingBookings.length, rejectedBookings.length, schedule.length]);

  return (
    <div className="admin-pro-shell">
      <Sidebar
        role="Admin"
        items={adminNavItems}
        activeItem={showIncharges ? "incharges" : activeSection}
        onSelect={handleSidebarSelect}
        onLogout={handleLogout}
      />

      <main className="admin-pro-main">
        <Navbar
          title="Admin Control Panel"
          subtitle="Live booking operations, approvals, and resource schedules."
          userRole="Admin"
        />

        {message ? <motion.div className="alert info" initial={{ opacity: 0 }} animate={{ opacity: 1 }}>{String(message)}</motion.div> : null}

        <motion.section
          className="admin-hero card"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.3 }}
        >
          <div>
            <p className="eyebrow">Operations Dashboard</p>
            <h2>Welcome back, Admin 👋</h2>
            <span>Review incoming requests, approve resources, and track outcomes in real time.</span>
          </div>
          <motion.button
            type="button"
            className="hero-refresh-btn"
            onClick={loadData}
            whileHover={{ scale: 1.04 }}
            whileTap={{ scale: 0.96 }}
          >
            Refresh
          </motion.button>
        </motion.section>

        {loading ? (
          <AdminSkeleton />
        ) : (
          <>
            <section className="admin-stat-grid">
              <StatCard tone="total" icon="T" label="Total Bookings" value={stats.total} delay={0.02} />
              <StatCard tone="pending" icon="P" label="Pending" value={stats.pending} delay={0.08} />
              <StatCard tone="approved" icon="A" label="Approved" value={stats.approved} delay={0.14} />
              <StatCard tone="rejected" icon="R" label="Rejected" value={stats.rejected} delay={0.2} />
            </section>

            <motion.section
              className="admin-workspace card"
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.3, delay: 0.12 }}
            >
              <div className="admin-workspace-header">
                <div>
                  <h3>Bookings</h3>
                  <p>Dynamic approval queue with live status segmentation.</p>
                </div>
                <div className="admin-tabs pro-tabs">
                  {tabs.map((tab) => (
                    <motion.button
                      key={tab}
                      type="button"
                      className={`tab-button ${activeTab === tab ? "active" : ""}`}
                      onClick={() => setActiveTab(tab)}
                      whileHover={{ scale: 1.03 }}
                      whileTap={{ scale: 0.96 }}
                    >
                      {tab}
                    </motion.button>
                  ))}
                </div>
              </div>

              <AdminBookingTable
                bookings={activeBookings}
                activeTab={activeTab}
                onApprove={handleApprove}
                onReject={openRejectModal}
              />
            </motion.section>
          </>
        )}
      </main>

      <InchargeModal open={showIncharges} groups={incharges} onClose={() => setShowIncharges(false)} />
      <RejectBookingModal
        booking={rejectBooking}
        reason={rejectReason}
        loading={rejectLoading}
        onReasonChange={setRejectReason}
        onClose={closeRejectModal}
        onSubmit={handleRejectSubmit}
      />
    </div>
  );
};

export default AdminDashboard;
